+void VisionOSXRInterface::_bind_methods() {
+	// Signals
+	for (int i = 0; i < VISIONOS_XR_SIGNAL_MAX; i++) {
+		ADD_SIGNAL(MethodInfo(get_signal_name((SignalEnum)i)));
+	}
