+	cp_drawable_encode_present(current_drawable, p_cmd_buffer->get_command_buffer());
+}
+
+void VisionOSXRInterface::end_frame() {
+	_THREAD_SAFE_METHOD_
+
+	if (!initialized) {
+		return;
+	}
